const o = measured.observed;
const raRestores = o.calls;                 // one `lw ra` per callee epilogue (lower bound on invocations)
const boundsLocalLoads = 2 * o.boundsTests; // 0xf1 does two sp-relative lw (position, receiver) if boundsTests counts 0xf1 executions
const ub = o.stackLoads - raRestores;
const r = {
  loadShareOfRetired: o.stackLoads / o.retired,
  ubLoads: ub, ubShareOfLoads: ub / o.stackLoads,
  ubRetiredPctIfDeleted: 100 * ub / o.retired, ubFramePctIfDeleted: 100 * ub / o.frameRetired,
  boundsLocalLoads, boundsShareOfLoads: boundsLocalLoads / o.stackLoads,
  otherLoads: ub - boundsLocalLoads,
  saveCostPerSreg: 2 * o.calls,
  hypotheticalFramePct: measured.hypothetical.predictedFullFrameReductionPercent,
  loadsPerCall: o.stackLoads / o.calls, storesPerCall: o.stackStores / o.calls,
  rowsPerStride: o.retired / o.stride
};
for (const k of [2,4,8]) r["netIfHalfForwarded_k"+k] = (ub*0.5 - k*2*o.calls);
JSON.stringify(r, null, 1)

