  {opcode:0x41,operands:[0]},{opcode:0x21,operands:[2]},
  {opcode:0x03,operands:[0x40]},
    {opcode:0xf1,operands:[0,2]},{opcode:0x2f,operands:[0,0]},{opcode:0x21,operands:[3]},
    {opcode:0x20,operands:[2]},{opcode:0x41,operands:[1]},{opcode:0x6a,operands:[]},{opcode:0x21,operands:[2]},
    {opcode:0x20,operands:[2]},{opcode:0x20,operands:[1]},{opcode:0x48,operands:[]},{opcode:0x0d,operands:[0]},
  {opcode:0x0b,operands:[]},
  {opcode:0x20,operands:[3]},{opcode:0x0b,operands:[]}];
const fnA = {params:["i32","i32"], nlocals:2};
const r1 = scoreLocals(fnA, ops);
const r2 = scoreLocals(fnA, [...ops.slice(0,-1), {opcode:0x10,operands:[0]}, {opcode:0x0b,operands:[]}]);
let err; try { scoreLocals(fnA, [{opcode:0x20,operands:[9]}]); } catch(e){ err = e.message; }
JSON.stringify({r1: {calls:r1.calls, homes:r1.homes, est:r1.estimate, s:r1.scored.map(x=>[x.local,x.loads,x.forwardLoads,x.stores,x.forwardStores,x.score])},
  r2: {calls:r2.calls, homes:r2.homes, saves:r2.saves}, err})

globalThis.scoreLocals2 = new Function(SRC + "; return scoreLocals;")();
const ops2 = [
  {opcode:0x41,operands:[0]},{opcode:0x21,operands:[2]},
  {opcode:0x03,operands:[0x40]},
    {opcode:0xf1,operands:[0,2]},{opcode:0x2f,operands:[0,0]},{opcode:0x21,operands:[3]},
    {opcode:0x20,operands:[2]},{opcode:0x41,operands:[1]},{opcode:0x6a,operands:[]},{opcode:0x21,operands:[2]},
    {opcode:0x20,operands:[2]},{opcode:0x20,operands:[1]},{opcode:0x48,operands:[]},{opcode:0x0d,operands:[0]},
  {opcode:0x0b,operands:[]},
  {opcode:0x20,operands:[3]},{opcode:0x0b,operands:[]}];
const fnB = {params:["i32","i32"], nlocals:2};
const s1 = scoreLocals2(fnB, ops2);
const s2 = scoreLocals2(fnB, [...ops2.slice(0,-1), {opcode:0x10,operands:[0]}, {opcode:0x0b,operands:[]}]);
let e2; try { scoreLocals2(fnB, [{opcode:0x20,operands:[9]}]); } catch(e){ e2 = e.message; }
JSON.stringify({s1: {calls:s1.calls, homes:s1.homes, est:s1.estimate, s:s1.scored.map(x=>[x.local,x.loads,x.forwardLoads,x.stores,x.forwardStores,x.score])},
  s2: {calls:s2.calls, homes:s2.homes, saves:s2.saves}, e2, big: scoreLocals2(fnB, {length:1}).decline})

globalThis.SRC2 = SRC
 .replace("const PRODUCES = new Set([0x41,", "const PRODUCES = new Set([0x28,0x2f,0x41,")
 .replace(" - (r.param && calls ? 0 : 0)", "")
 .replace(/const pool = calls \? cfg\.callSaved : cfg\.callFree;/, `// Call-free: parameter i>=1 stays in a_i (no copy); a0 is reserved, so p0 and plain locals share the rest.
  const fixed = new Map();
