  const pool = (calls ? cfg.callSaved : cfg.callFree).filter(reg => ![...fixed.values()].includes(reg));`)
 .replace(/const homes = ranked\.slice\(0, pool\.length\)\.map\(\(r, j\) => \(\{local: r\.local, reg: pool\[j\], score: r\.score\}\)\);/,
 `const homes = []; let next = 0;
  for (const r of ranked) {
    const reg = fixed.get(r.local) ?? pool[next];
    if (reg === undefined) continue;
    if (!fixed.has(r.local)) next++;
    homes.push({local: r.local, reg, score: r.score});
  }`);
globalThis.scoreLocals3 = new Function(SRC2 + "; return scoreLocals;")();
const t1 = scoreLocals3({params:["i32","i32"], nlocals:2}, ops2);
const t2 = scoreLocals3({params:["i32","i32"], nlocals:2}, [...ops2.slice(0,-1), {opcode:0x10,operands:[0]}, {opcode:0x0b,operands:[]}]);
JSON.stringify({t1: t1.homes, est: t1.estimate, t2: t2.homes, saves: t2.saves, len: SRC2.length})

